import{_ as d,c as e,o as a,at as r}from"./chunks/framework.mXguc-v6.js";const u=JSON.parse('{"title":"前端框架对比","description":"","frontmatter":{},"headers":[],"relativePath":"views/interview/comparisons/framework-comparison.md","filePath":"views/interview/comparisons/framework-comparison.md","lastUpdated":null}'),s={name:"views/interview/comparisons/framework-comparison.md"};function n(o,t,c,l,i,h){return a(),e("div",null,t[0]||(t[0]=[r(`<h1 id="前端框架对比" tabindex="-1">前端框架对比 <a class="header-anchor" href="#前端框架对比" aria-label="Permalink to &quot;前端框架对比&quot;">​</a></h1><blockquote><p>React / Vue3 / Angular 核心差异速查 基于 W1 D1~D3 实战沉淀</p></blockquote><h2 id="设计哲学" tabindex="-1">设计哲学 <a class="header-anchor" href="#设计哲学" aria-label="Permalink to &quot;设计哲学&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>React</th><th>Vue3</th><th>Angular</th></tr></thead><tbody><tr><td>范式</td><td>函数式 + 不可变</td><td>响应式 + 可变</td><td>响应式 + DI</td></tr><tr><td>类型</td><td>TS 推荐</td><td>TS 推荐</td><td>TS 必选</td></tr><tr><td>模板</td><td>JSX</td><td>SFC 模板 + JSX</td><td>HTML 模板</td></tr><tr><td>组件模型</td><td>函数组件</td><td>SFC (script setup)</td><td>Class + 函数 (17+ 也支持函数)</td></tr><tr><td>状态管理</td><td>Hooks + Context</td><td>ref/reactive + Pinia</td><td>Signals + RxJS</td></tr><tr><td>DI</td><td>无（手动 props）</td><td>无（provide/inject）</td><td>内置 DI 容器</td></tr><tr><td>模块化</td><td>ES modules</td><td>ES modules</td><td>NgModule / Standalone (17+)</td></tr></tbody></table><h2 id="响应式原理" tabindex="-1">响应式原理 <a class="header-anchor" href="#响应式原理" aria-label="Permalink to &quot;响应式原理&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>React</th><th>Vue3</th><th>Angular</th></tr></thead><tbody><tr><td><strong>机制</strong></td><td>Fiber 链表 + 不可变引用对比</td><td>Proxy 代理对象，拦截 get/set</td><td>Zone.js 拦截异步 + Signal</td></tr><tr><td><strong>数据修改</strong></td><td>不可变，必须返回新引用</td><td>可变，直接改属性</td><td>不可变（Signal 自动检测）</td></tr><tr><td><strong>依赖追踪</strong></td><td>手动 deps 数组</td><td>自动（effect 系统）</td><td>Signal 自动 / Zone.js 全量</td></tr><tr><td><strong>闭包陷阱</strong></td><td>常见（过期闭包）</td><td>不存在</td><td>不存在（Signal + effect）</td></tr></tbody></table><p>React 的 <code>useState</code> → 返回 <code>[value, setter]</code>，必须用 setter 传新值。 Vue3 的 <code>ref</code> → 返回响应式对象，直接改 <code>.value</code>。 Angular 的 <code>signal</code> → 返回 getter 函数，<code>.set()</code> / <code>.update()</code> 更新。</p><h2 id="渲染机制" tabindex="-1">渲染机制 <a class="header-anchor" href="#渲染机制" aria-label="Permalink to &quot;渲染机制&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>React</th><th>Vue3</th><th>Angular</th></tr></thead><tbody><tr><td><strong>虚拟 DOM</strong></td><td>全量创建 + 全量 diff</td><td>只创建动态节点（PatchFlags）</td><td>无虚拟 DOM（模板编译直接操作 DOM）</td></tr><tr><td><strong>编译优化</strong></td><td>几乎没有（JSX 全动态）</td><td>静态提升 + Block Tree + PatchFlags</td><td>AOT 编译，模板直接生成指令</td></tr><tr><td><strong>优化手段</strong></td><td>memo / useCallback / useMemo</td><td>默认已优化</td><td>OnPush 策略 + trackBy</td></tr><tr><td><strong>渲染触发</strong></td><td>整个组件重渲染 → diff</td><td>精确到动态节点</td><td>Zone.js 拦截异步 → 全树检查</td></tr><tr><td><strong>diff 算法</strong></td><td>右端优先（React 16+）</td><td>双端 diff</td><td>无（无虚拟 DOM）</td></tr></tbody></table><h2 id="性能优化策略" tabindex="-1">性能优化策略 <a class="header-anchor" href="#性能优化策略" aria-label="Permalink to &quot;性能优化策略&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>React</th><th>Vue3</th><th>Angular</th></tr></thead><tbody><tr><td>避免子组件重渲染</td><td><code>React.memo</code> + <code>useCallback</code></td><td>默认跳过</td><td><code>OnPush</code> 策略</td></tr><tr><td>派生状态缓存</td><td><code>useMemo</code></td><td><code>computed</code></td><td><code>computed</code> (Signal)</td></tr><tr><td>大列表优化</td><td><code>key</code> + 虚拟滚动</td><td><code>:key</code> + 虚拟滚动</td><td><code>track</code> (<code>@for</code>) + 虚拟滚动</td></tr><tr><td>条件渲染</td><td><code>{cond &amp;&amp; &lt;A/&gt;}</code></td><td><code>v-if / v-show</code></td><td><code>@if / @else</code></td></tr><tr><td>避免闭包陷阱</td><td><code>useCallback</code> + deps</td><td>不存在</td><td>不存在</td></tr></tbody></table><h2 id="开发体验" tabindex="-1">开发体验 <a class="header-anchor" href="#开发体验" aria-label="Permalink to &quot;开发体验&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>React</th><th>Vue3</th><th>Angular</th></tr></thead><tbody><tr><td><strong>TS 集成</strong></td><td>泛型组件需额外工作</td><td><code>defineProps&lt;{}&gt;()</code> 原生支持</td><td>强制 TS，原生支持最完善</td></tr><tr><td><strong>双向绑定</strong></td><td>手动 <code>value + onChange</code></td><td><code>v-model</code> / <code>defineModel</code></td><td><code>[(ngModel)]</code> / <code>model()</code></td></tr><tr><td><strong>表单处理</strong></td><td>受控 / 非受控</td><td><code>v-model</code></td><td><code>FormsModule</code> / <code>ReactiveForms</code></td></tr><tr><td><strong>子传父</strong></td><td>回调 props</td><td><code>emit</code></td><td><code>output()</code></td></tr><tr><td><strong>插槽</strong></td><td><code>{children}</code> / render props</td><td><code>&lt;slot&gt;</code></td><td><code>&lt;ng-content&gt;</code></td></tr><tr><td><strong>样式</strong></td><td>className / CSS-in-JS</td><td><code>&lt;style scoped&gt;</code></td><td><code>[class.active]</code> / <code>:host</code></td></tr><tr><td><strong>HTTP</strong></td><td>fetch / axios</td><td>fetch / axios</td><td>HttpClient（内置）</td></tr><tr><td><strong>路由</strong></td><td>React Router</td><td>Vue Router</td><td>Router（内置）</td></tr></tbody></table><h2 id="变更检测对比" tabindex="-1">变更检测对比 <a class="header-anchor" href="#变更检测对比" aria-label="Permalink to &quot;变更检测对比&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Angular: Zone.js 拦截 setTimeout/Promise/事件 → 全树检查</span></span>
<span class="line"><span>         ↓ OnPush 缩到只检查当前组件（类似 React.memo）</span></span>
<span class="line"><span>         ↓ Signal 精确到消费者</span></span>
<span class="line"><span></span></span>
<span class="line"><span>React:   setState → 当前组件 + 整个子树递归 diff</span></span>
<span class="line"><span>         ↓ memo/useCallback 控制子组件跳不跳过</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Vue3:    ref.value = x → 精确到动态节点</span></span>
<span class="line"><span>         ↓ 不需要任何手动优化</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h2 id="编译策略" tabindex="-1">编译策略 <a class="header-anchor" href="#编译策略" aria-label="Permalink to &quot;编译策略&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>React</th><th>Vue3</th><th>Angular</th></tr></thead><tbody><tr><td><strong>编译时机</strong></td><td>运行时</td><td>构建时 + 运行时</td><td>AOT 编译（构建时）</td></tr><tr><td><strong>模板</strong></td><td>JSX = JS</td><td>SFC 模板</td><td>HTML 模板</td></tr><tr><td><strong>产物</strong></td><td>createElement 调用</td><td>带 PatchFlags 的 render 函数</td><td>直接操作 DOM 的指令</td></tr><tr><td><strong>优化空间</strong></td><td>小（JSX 全动态）</td><td>大（模板可静态分析）</td><td>大（AOT + 模板）</td></tr></tbody></table><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Angular 没有虚拟 DOM：模板编译成直接操作 DOM 的指令</span></span>
<span class="line"><span>Vue3 有虚拟 DOM：但编译优化了动态节点追踪</span></span>
<span class="line"><span>React 有虚拟 DOM：全量 diff，靠 Fiber 分片缓解</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="何时用什么" tabindex="-1">何时用什么 <a class="header-anchor" href="#何时用什么" aria-label="Permalink to &quot;何时用什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>推荐框架</th></tr></thead><tbody><tr><td>大型企业应用</td><td>Angular（结构化/类型安全/内置齐全）</td></tr><tr><td>快速迭代 + 灵活</td><td>React（生态最大/社区最活跃）</td></tr><tr><td>中小型 + 快速上手</td><td>Vue3（学习曲线最低/渐进式）</td></tr><tr><td>全栈 SSR</td><td>Next.js (React) / Nuxt (Vue3) / Angular Universal</td></tr><tr><td>跨端移动</td><td>RN (React) / uni-app (Vue)</td></tr><tr><td>微前端</td><td>三者均可（MF / qiankun）</td></tr></tbody></table>`,20)]))}const b=d(s,[["render",n]]);export{u as __pageData,b as default};
